const el = (id) => document.getElementById(id);
const classes = ["PHONE", "DOCUMENT", "WATER_BOTTLE"];
const state = { model: null, webcam: null, running: false, stableName: "", stableSince: 0, cooldownUntil: 0, score: 0, streak: 0, totalScans: 0, counts: { PHONE: 0, DOCUMENT: 0, WATER_BOTTLE: 0 }, currentChallenge: "PHONE", previousAgentMessage: "" };
const examples = [["PHONE", .96], ["DOCUMENT", .93], ["WATER_BOTTLE", .92], ["NO_OBJECT", .94]];
function addLog(text) { const li = document.createElement("li"); li.innerHTML = "<time>" + new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }) + "</time><span></span>"; li.querySelector("span").textContent = text; el("history").prepend(li); }
function renderDecision(type, title, text, icon = "✦") { el("decisionType").textContent = type; el("decisionTitle").textContent = title; el("decisionText").textContent = text; document.querySelector(".message-icon").textContent = icon; }
function setPrediction(name, confidence) { el("predictionName").textContent = name.replaceAll("_", " "); el("confidenceText").textContent = Math.round(confidence * 100) + "%"; el("confidenceMeter").style.width = Math.round(confidence * 100) + "%"; el("predictionIcon").textContent = ({ PHONE: "▣", DOCUMENT: "▤", WATER_BOTTLE: "◒", NO_OBJECT: "○" })[name] || "!"; }
function renderState() { el("scoreState").textContent = state.score; el("challengeState").textContent = state.currentChallenge.replace("_", " "); el("scanState").textContent = state.totalScans; }
function fallbackDecision(name) { const next = classes[(classes.indexOf(name) + 1) % classes.length]; return { accepted: true, action: "ACCEPT_SCAN", scoreDelta: name === state.currentChallenge ? 10 : 2, nextChallenge: next, feedback: name === state.currentChallenge ? "Challenge complete. Great focus habit!" : "Correctly spotted. Try the requested challenge next.", tip: "Keep your desk clear and reduce distractions." }; }
async function askAgent(name, confidence) {
  renderDecision("AGENT THINKING", "Checking your session…", "The Agent is choosing the next focus habit.", "◌");
  const payload = { detectedClass: name, confidence, currentScore: state.score, streak: state.streak, totalScans: state.totalScans, phoneCount: state.counts.PHONE, documentCount: state.counts.DOCUMENT, waterBottleCount: state.counts.WATER_BOTTLE, currentChallenge: state.currentChallenge, previousAgentMessage: state.previousAgentMessage };
  let decision;
  try { const response = await fetch("/api/agent", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload) }); if (!response.ok) throw new Error(); decision = await response.json(); }
  catch { decision = fallbackDecision(name); addLog("Agent server is not configured yet; demo decision used."); }
  if (decision.action === "ACCEPT_SCAN" && decision.accepted) { state.score += decision.scoreDelta; state.streak++; state.totalScans++; state.counts[name]++; } else state.streak = 0;
  state.currentChallenge = decision.nextChallenge; state.previousAgentMessage = decision.feedback; renderState();
  renderDecision(decision.action === "ACCEPT_SCAN" ? "AGENT DECISION" : "TRY AGAIN", decision.feedback, "Tip: " + decision.tip, decision.action === "ACCEPT_SCAN" ? "✓" : "↻");
  addLog(name + " detected (" + Math.round(confidence * 100) + "%). Agent: " + decision.feedback);
}
async function loadModel() { let url = el("modelUrl").value.trim(); if (!url) return; if (!url.endsWith("/")) url += "/"; try { el("modelState").textContent = "Connecting…"; state.model = await tmImage.load(url + "model.json", url + "metadata.json"); localStorage.setItem("focusguard-model-url", url); el("modelState").textContent = "Connected"; renderDecision("MODEL CONNECTED", "Your detector is ready.", "Enable your camera and show a trained desk object.", "✓"); addLog("Teachable Machine model connected successfully."); } catch { el("modelState").textContent = "Connection failed"; renderDecision("CONNECTION ERROR", "Could not load that model.", "Check the published model URL and try again.", "!"); } }
async function enableCamera() { if (!state.model) return renderDecision("MODEL NEEDED", "Connect a model first.", "The camera needs a published Teachable Machine model.", "!"); try { state.webcam = new tmImage.Webcam(480, 360, true); await state.webcam.setup(); await state.webcam.play(); state.running = true; const video = el("webcam"); video.srcObject = state.webcam.webcam.srcObject; video.style.display = "block"; el("cameraEmpty").style.display = "none"; el("cameraStatus").textContent = "Camera live"; el("cameraBtn").textContent = "Camera is live"; addLog("Camera enabled locally."); loop(); } catch { renderDecision("CAMERA ERROR", "Camera permission was not granted.", "Allow camera access in browser settings, then try again.", "!"); } }
async function processDetection(name, confidence) { setPrediction(name, confidence); if (name === "NO_OBJECT" || confidence < .9) { state.stableName = ""; return renderDecision("WAITING FOR A STEADY OBJECT", "Hold an object steady.", "Show a trained object clearly for about one second.", "⌁"); } const now = Date.now(); if (state.stableName !== name) { state.stableName = name; state.stableSince = now; return renderDecision("CHECKING DETECTION", "Keep it steady…", "High confidence detected. The Agent will receive it after one second.", "◌"); } if (now - state.stableSince >= 1000 && now >= state.cooldownUntil) { state.cooldownUntil = now + 3000; state.stableName = ""; await askAgent(name, confidence); } }
async function loop() { if (!state.running || !state.model) return; state.webcam.update(); const results = await state.model.predict(state.webcam.canvas); const best = results.reduce((a, b) => a.probability > b.probability ? a : b); await processDetection(best.className.toUpperCase().replaceAll(" ", "_"), best.probability); requestAnimationFrame(loop); }
el("connectBtn").addEventListener("click", loadModel); el("cameraBtn").addEventListener("click", enableCamera);
el("demoBtn").addEventListener("click", async () => { const [name, confidence] = examples[Math.floor(Math.random() * examples.length)]; const visual = { PHONE: ["📱", "Phone detected"], DOCUMENT: ["📄", "Document detected"], WATER_BOTTLE: ["💧", "Water bottle detected"], NO_OBJECT: ["⌁", "Desk is clear"] }[name]; const stage = el("cameraEmpty"); stage.classList.add("demo-scene"); stage.style.display = "grid"; stage.innerHTML = '<div class="demo-object">' + visual[0] + '</div><p class="demo-label">DEMO DETECTION</p><p class="demo-subtitle">' + visual[1] + " · " + Math.round(confidence * 100) + "% confidence</p>"; if (name === "NO_OBJECT") { setPrediction(name, confidence); return renderDecision("WAITING FOR INPUT", "Desk is clear.", "Show a trained object to continue.", "⌁"); } setPrediction(name, confidence); await askAgent(name, confidence); });
el("focusBtn").textContent = "Reset session"; el("focusBtn").addEventListener("click", () => { Object.assign(state, { score: 0, streak: 0, totalScans: 0, counts: { PHONE: 0, DOCUMENT: 0, WATER_BOTTLE: 0 }, currentChallenge: "PHONE", previousAgentMessage: "" }); renderState(); addLog("Session reset."); renderDecision("SESSION RESET", "New challenge: PHONE", "Show a phone to begin a new focus session.", "↺"); });
el("clearLog").addEventListener("click", () => { el("history").innerHTML = "<li><time>NOW</time><span>Decision log cleared.</span></li>"; });
el("modelUrl").value = localStorage.getItem("focusguard-model-url") || localStorage.getItem("cyberdesk-model-url") || "https://teachablemachine.withgoogle.com/models/kt4nBUJJC/"; renderState(); loadModel();

